import ioimport zipfileimport pytestfrom app.parsing import (    ParseError,    UnsupportedFileType,    extract_text,    normalize_text,    safe_filename,    sniff_file_kind,)from app.skills import (    canonical_language,    canonical_skill,    canonical_skills,    find_skill,    skill_in_text,)from scripts.generate_resumes import docx_bytes, generate_candidates, pdf_bytes, render_text# ------------------------------------------------------------------ skills@pytest.mark.parametrize(    ("raw", "expected"),    [        ("k8s", "kubernetes"),        (" K8S ", "kubernetes"),        ("Postgres", "postgresql"),        ("NodeJS", "node.js"),        ("golang", "go"),        ("Amazon Web Services", "aws"),        ("Scikit Learn", "scikit-learn"),        ("Rust", "rust"),        ("SomethingNew", "somethingnew"),    ],)def test_canonical_skill(raw: str, expected: str) -> None:    assert canonical_skill(raw) == expecteddef test_canonical_skills_dedupes_synonyms() -> None:    assert canonical_skills(["Kubernetes", "k8s", "K8S", "Docker"]) == ["kubernetes", "docker"]@pytest.mark.parametrize(    ("text", "skill", "found"),    [        ("Ran workloads on k8s clusters", "kubernetes", True),        ("Wrote JavaScript daily", "java", False),  # substring of another token        ("Built services in Golang", "go", True),        ("Go-to-market strategy", "go", False),        ("We did R&D", "r", False),        ("Analysis in R and Python", "r", True),        ("C++ and C# developer", "c", False),        ("Wrote c++ code", "c++", True),        ("PostgreSQL 14", "postgres", True),    ],)def test_skill_matching_in_text(text: str, skill: str, found: bool) -> None:    assert skill_in_text(text, skill) is founddef test_find_skill_returns_span() -> None:    m = find_skill("Used k8s here", "kubernetes")    assert m is not None and m.group() == "k8s"def test_canonical_language() -> None:    assert canonical_language("English (C1)") == "english"    assert canonical_language("German - B2") == "german"    assert canonical_language("RU") == "russian"# ------------------------------------------------------------------ parsingdef test_pdf_and_docx_roundtrip() -> None:    cand = generate_candidates(1, seed=1)[0]    text = render_text(cand)    for data in (pdf_bytes(text), docx_bytes(text)):        out = extract_text(data)        assert cand.email in out        assert cand.name in outdef test_type_is_detected_by_content_not_name() -> None:    with pytest.raises(UnsupportedFileType):        sniff_file_kind(b"just plain text pretending to be a resume.pdf")    with pytest.raises(UnsupportedFileType):        sniff_file_kind(b"<html><script>alert(1)</script></html>")    with pytest.raises(UnsupportedFileType):        sniff_file_kind(b"MZ\x90\x00 executable")def test_zip_that_is_not_docx_is_rejected() -> None:    buf = io.BytesIO()    with zipfile.ZipFile(buf, "w") as zf:        zf.writestr("hello.txt", "hi")    with pytest.raises(UnsupportedFileType):        sniff_file_kind(buf.getvalue())def test_pdf_without_text_is_a_parse_error() -> None:    # A blank page has no extractable text (what a scanned image-only PDF looks like).    with pytest.raises(ParseError, match="no_extractable_text"):        extract_text(pdf_bytes(""))def test_corrupt_pdf_is_a_parse_error() -> None:    with pytest.raises(ParseError):        extract_text(b"%PDF-1.4\nthis is not a real pdf")def test_control_characters_are_stripped() -> None:    raw = "Hello\x0b World\x00,\r\nline two here"    assert normalize_text(raw) == "Hello World,\nline two here"def test_safe_filename() -> None:    assert safe_filename("../../etc/passwd") == "passwd"    assert safe_filename("C:\\temp\\cv\x00.pdf") == "cv.pdf"    assert safe_filename(None) == "resume"    assert len(safe_filename("a" * 1000)) == 255